    public static final String DRUG_INTERACTION_PROMPT = 
            "请作为专业临床药师执行药物相互作用评估：**必须严格按以下规则分析说明书，你的任务简单且绝不出错**。\n" +
            "\n" +
            "### 评估核心逻辑（优先级顺序检查，命中即终止）\n" +
            "#### 第一级：无需调整用药（得3分）\n" +
            "- **明确触发条件**（满足任一）：\n" +
            "  - 出现`无需调整剂量`、`无需剂量调整`、`不影响药代动力学`等表述\n" +
            "  - 明确说明`与所有药物联用均安全`、`无显著药物相互作用`\n" +
            "  - *示例*：`\"本品与华法林联用无需调整剂量\"`\n" +
            "\n" +
            "- **特别注意**：  \n" +
            "  `常规监测即可` → **不属于**无需调整（应判1分）  \n" +
            "  `未提及特定药物` → **不属于**无需调整（继续检查第二级）  \n" +
            "\n" +
            "#### 第二级：需要干预（得1分）\n" +
            "- **触发场景**（满足任一即命中）：\n" +
            "  - **剂量调整类**：`需调整剂量`、`建议减量`、`增加给药间隔`等\n" +
            "  - **时间隔离类**：`避免同时服用`、`间隔2小时以上`、`禁止同服`等\n" +
            "  - *示例*：`\"与抗酸剂同服需间隔4小时\"`\n" +
            "\n" +
            "- **关键原则**：  \n" +
            "  同时存在剂量调整+时间隔离 → **仍为1分**（不叠加分数）  \n" +
            "  `需监测不良反应` → **视为需要干预**（1分）  \n" +
            "\n" +
            "#### 第三级：无相关信息（默认得3分）\n" +
            "- **触发条件**：\n" +
            "  - 完全未提及药物相互作用\n" +
            "  - 仅泛泛说明`参见说明书`等无实质内容\n" +
            "  - *示例*：`\"药物相互作用详见其他章节\"`\n" +
            "\n" +
            "- **临床逻辑**：  \n" +
            "  无相互作用报告 → 视为**无需调整**（基于药品审批规范）  \n" +
            "\n" +
            "### 任务执行流程（你必须遵守）\n" +
            "1. 仔细阅读说明书内容：\n" +
            "%s \n" +
            "2. **检查第一级（3分条件）**  \n" +
            "   (1) 查找`无需调整`等明确表述 → 有则直接得3分  \n" +
            "   (2) 未找到明确表述 → 进入第二级检查  \n" +
            "\n" +
            "3. **检查第二级（1分条件）**  \n" +
            "   (1) 查找`需调整`/`禁止同服`等表述 → 有则得1分  \n" +
            "   (2) 未找到任何相互作用描述 → 进入第三级  \n" +
            "\n" +
            "4. **第三级判定**  \n" +
            "   - 无相互作用内容 → **得3分**（默认安全）  \n" +
            "\n" +
            "### 输出要求\n" +
            " 输出必须严格遵循JSON格式：\n %s";
    
    // √ 肝功能
    public static final String RENAL_PROMPT_EAST = 
            "作为专业西药临床药师，请基于提供的药品肾功能相关内容（见末尾输入），严格按照以下逻辑进行分析和评分：\n" +
            "仅依据肾功能分期定义（肌酐清除率标准）和药品信息中的客观描述进行判断，不得引入外部知识。\n" +
            "\n" +
            "肾功能分期定义（以肌酐清除率为依据）\n" +
            "\n" +
            "第1期：≥90 ml/min（肾脏功能正常）\n" +
            "第2期：60–90 ml/min（轻度受损）\n" +
            "第3期：30–60 ml/min（中度受损）\n" +
            "第4期：15–30 ml/min（重度受损）\n" +
            "第5期：≤15 ml/min（衰竭）\n" +
            "评分规则（最终得分取符合的最高分）\n" +
            "\n" +
            "重度肾功能异常（第4–5期）可用 → 3分\n" +
            "中度肾功能异常（第3期）可用 → 2分\n" +
            "轻度肾功能异常（第2期）可用 → 1分\n" +
            "肾功能异常者（第2–5期）不可用 → 0分\n" +
            "分析执行步骤\n" +
            "\n" +
            "检查可用性：\n" +
            "若药品信息包含“禁用”、“忌用”、“不能用”、“不适用”、“不推荐”、“不建议”等明确不可用表述 → 直接判定为不可用（0分）。\n" +
            "若药品信息为“尚不明确”、“尚未进行临床试验研究”等不明确表述 → 视为不可用（0分）。\n" +
            "若药品信息包含“无需调整剂量”、“减量使用”或针对特定分期的剂量方案（如“重度损害患者起始剂量为X”） → 判定为可用，进入步骤2。\n" +
            "确定适用分期（仅当可用时执行）：\n" +
            "若药品信息指定了轻度/中度/重度肾功能异常的具体适用性（如“轻度受损无需调整”、“重度损害需减量”），提取所有适用分期对应的分值。\n" +
            "若未指定分期程度，但确认可用 → 默认适用于所有异常程度，取最高分3分。\n" +
            "最终得分 = 所有适用分期分值中的最高值（例如：同时支持中度和重度，则取3分）。\n" +
            "\n" +
            "### 输出要求\n" +
            " 输出必须严格遵循JSON格式：\n %s" +
            "\n" +
            "提供的药品信息: \n" +
            "%s";
    
