            "(2) 有无类型2表述 → 有则**0.5分**，无则继续  \n" +
            "(3) 有无类型0表述 → 有则**0分**，否则默认**0分**  \n" +
            "3. 生成分析过程（`process`字段用中文分步说明）\n" +
            "\n" +
            "### 输出要求\n" +
            " 输出必须严格遵循JSON格式：\n %s";;
    
