            "### 判定标准\n" +
            "#### ✔ 属于肾功能异常用药内容（需提取）：\n" +
            "- 明确提及\"肾功能不全\"、\"肾功能异常\"、\"肌酐清除率\"、\"eGFR\"、\"CrCl\"等关键词\n" +
            "- 包含肾功能分级（如\"CKD 3/4/5期\"、\"轻/中/重度肾功能不全\"、\"CrCl<30mL/min\"）\n" +
            "- 说明剂量调整方案（如\"CrCl 30-50mL/min减量至50%\"、\"透析患者禁用\"）\n" +
            "- 提供用药监测建议（如\"定期监测肌酐水平\"、\"eGFR下降需调整剂量\"）\n" +
            "- 包含肾功能相关禁忌（如\"严重肾功能不全禁用\"、\"透析患者需调整给药时间\"）\n" +
            "\n" +
            "#### ✘ 不属于肾功能异常用药内容（不提取）：\n" +
            "- 仅提及\"肝功能不全\"或其它器官功能不全的内容\n" +
            "- 通用不良反应描述（如\"少数患者出现肌酐升高\"）\n" +
            "- 临床试验中包含肾功能异常患者但无具体用药指导\n" +
            "- 与肾功能无关的禁忌症说明\n" +
            "\n" +
            "### JSON输出规范（严格遵循）\n" +
            "{\n" +
            "  \"hasRenalInfo\": \"boolean值，当renalContent非空时为true，否则false\",\n" +
            "  \"renalContent\": \"string值，提取的原文内容（保留标点），无则空字符串\",\n" +
            "  \"kidneyClassification\": \"string值，肾功能分级描述，无则空字符串\",\n" +
            "  \"dosageAdjustment\": \"string值，剂量调整信息，无则空字符串\"\n" +
            "}\n" +
            "\n" +
            "### 提取规则\n" +
            "1. **renalContent**：\n" +
            "   - 必须是**连续的原文片段**（不做任何修改，但是不要显示重复内容）\n" +
            "   - 长度≤100字，截取核心部分\n" +
            "   - 多处相关内容用\";\"分隔\n" +
            "   - 无相关内容时留空字符串\n" +
            "\n" +
            "2. **kidneyClassification**：\n" +
            "   - 仅提取明确的肾功能分级表述\n" +
            "   - 格式示例：\"CKD 3期\"、\"CrCl 30-50mL/min\"、\"eGFR<30mL/min/1.73m²\"\n" +
            "   - 无分级信息时留空\n" +
            "\n" +
            "3. **dosageAdjustment**：\n" +
            "   - 仅提取剂量调整相关描述\n" +
            "   - 格式示例：\"CrCl<30mL/min减量至50%\"、\"透析后补充剂量\"\n" +
            "   - 无剂量调整信息时留空\n" +
            "\n" +
            "### 处理流程\n" +
            "1. 扫描文本寻找肾功能相关关键词\n" +
            "2. 提取完整相关语句（保持原文）\n" +
            "3. 从提取内容中分离肾功能分级和剂量调整信息\n" +
            "4. 按规则填充JSON字段\n" +
            "5. 根据renalContent是否为空设置hasRenalInfo\n" +
            "\n" +
            "### 输出示例\n" +
            "✅ 有效示例1（有肾功能分级）：\n" +
            "{\n" +
            "  \"hasRenalInfo\": true,\n" +
            "  \"renalContent\": \"CKD 3期患者剂量减半；4期患者剂量减少至30%；5期或透析患者禁用\",\n" +
            "  \"kidneyClassification\": \"CKD 3/4/5期\",\n" +
            "  \"dosageAdjustment\": \"3期剂量减半；4期减至30%；5期或透析禁用\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例2（有剂量调整）：\n" +
            "{\n" +
            "  \"hasRenalInfo\": true,\n" +
            "  \"renalContent\": \"肌酐清除率30-50mL/min剂量调整为10mg；<30mL/min剂量调整为5mg\",\n" +
            "  \"kidneyClassification\": \"CrCl 30-50mL/min; <30mL/min\",\n" +
            "  \"dosageAdjustment\": \"30-50mL/min: 10mg; <30mL/min: 5mg\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例3（无肾功能相关信息）：\n" +
            "{\n" +
            "  \"hasRenalInfo\": false,\n" +
            "  \"renalContent\": \"\",\n" +
            "  \"kidneyClassification\": \"\",\n" +
            "  \"dosageAdjustment\": \"\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例4（多条信息）：\n" +
            "{\n" +
            "  \"hasRenalInfo\": true,\n" +
            "  \"renalContent\": \"eGFR<30mL/min/1.73m²患者应避免使用；使用期间需监测肾功能；透析患者应在透析后给药\",\n" +
            "  \"kidneyClassification\": \"eGFR<30mL/min/1.73m²\",\n" +
            "  \"dosageAdjustment\": \"透析患者应在透析后给药\"\n" +
            "}\n" +
            "\n" +
            "### 绝对禁止\n" +
            "× 修改原文表述\n" +
            "× 添加解释性内容\n" +
            "× 多次输出JSON\n" +
            "× 使用非中文字符\n" +
            "× 对内容进行推断或总结\n" +
            "\n" +
            "请立即处理以下说明书内容：\n" +
            "\"\"\"\n" +
            "%s\n" +
            "\"\"\"\n";

