            "     * 完全重复表述：仅保留首次出现内容\n" +
            "     * 语义重复表述：保留信息最完整的一条\n" +
            "     * 例1：\"妊娠期禁用\"和\"孕妇禁用\"→ 仅保留\"妊娠期禁用\"（更正式表述）\n" +
            "     * 例2：\"FDA妊娠分级C级\"出现多次→ 仅保留一次\n" +
            "     * 例3：\"动物实验显示有致畸风险；孕妇用药需严格遵医嘱；动物实验显示有致畸风险\"→ 自动去重为\"动物实验显示有致畸风险；孕妇用药需严格遵医嘱\"\n" +
            "   - 多处有效内容用\"；\"连接（中文分号）\n" +
            "   - 禁止任何形式的改写或总结" +
            "\n" +
            "2. **pregnancyCategory**：\n" +
            "   - 仅提取明确的妊娠分级表述\n" +
            "   - 格式示例：\"FDA妊娠分级C级\"、\"妊娠期用药分类III级\"\n" +
            "   - 无分级信息时留空\n" +
            "\n" +
            "3. **usageGuidance**：\n" +
            "   - 仅提取使用建议描述\n" +
            "   - 格式示例：\"妊娠期禁用\"、\"仅在潜在益处大于风险时使用\"\n" +
            "   - 无使用建议时留空\n" +
            "\n" +
            "### 处理流程\n" +
            "1. 扫描文本寻找妊娠相关关键词\n" +
            "2. 提取完整相关语句（保持原文）\n" +
            "3. 从提取内容中分离分级和使用建议信息\n" +
            "4. 按规则填充JSON字段\n" +
            "5. 根据pregnancyContent是否为空设置hasPregnancyInfo\n" +
            "\n" +
            "### 输出示例\n" +
            "✅ 有效示例1（有妊娠分级）：\n" +
            "{\n" +
            "  \"hasPregnancyInfo\": true,\n" +
            "  \"pregnancyContent\": \"FDA妊娠分级C级，动物研究显示有不良影响，但缺乏孕妇对照研究\",\n" +
            "  \"pregnancyCategory\": \"FDA妊娠分级C级\",\n" +
            "  \"usageGuidance\": \"仅在潜在益处大于风险时使用\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例2（有禁忌说明）：\n" +
            "{\n" +
            "  \"hasPregnancyInfo\": true,\n" +
            "  \"pregnancyContent\": \"妊娠期妇女禁用；尤其妊娠前三个月禁用\",\n" +
            "  \"pregnancyCategory\": \"\",\n" +
            "  \"usageGuidance\": \"妊娠期妇女禁用，尤其妊娠前三个月\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例3（无妊娠信息）：\n" +
            "{\n" +
            "  \"hasPregnancyInfo\": false,\n" +
            "  \"pregnancyContent\": \"\",\n" +
            "  \"pregnancyCategory\": \"\",\n" +
            "  \"usageGuidance\": \"\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例4（多条信息）：\n" +
            "{\n" +
            "  \"hasPregnancyInfo\": true,\n" +
            "  \"pregnancyContent\": \"动物实验显示有致畸风险；孕妇用药需严格遵医嘱；FDA妊娠分级D级\",\n" +
            "  \"pregnancyCategory\": \"FDA妊娠分级D级\",\n" +
            "  \"usageGuidance\": \"孕妇用药需严格遵医嘱\"\n" +
            "}\n" +
            "\n" +
            "### 绝对禁止\n" +
            "× 修改原文表述\n" +
            "× 添加解释性内容\n" +
            "× 多次输出JSON\n" +
            "× 使用非中文字符\n" +
            "× 对内容进行推断或总结\n" +
            "× 忽略去重要求保留重复内容\n" +
            "\n" +
            "请立即处理以下说明书内容：\n" +
            "\"\"\"\n" +
            "%s\n" +
            "\"\"\"\n";

    public static final String CONTENT_EXTRACTION_CHILDREN_PROMPT = 
            "请作为医药信息提取专家执行儿童用药内容识别任务：**仅需执行内容提取，不进行任何判断或评分**。\n" +
            "\n" +
            "### 任务说明\n" +
            "1. 仔细阅读输入的药品说明书片段\n" +
            "2. **精准提取**所有与儿童用药直接相关的内容\n" +
            "3. **仅返回指定JSON**，无任何额外解释\n" +
            "\n" +
            "### 判定标准\n" +
            "#### ✔ 属于儿童用药内容（需提取）：\n" +
            "- 明确提及\"儿童\"、\"小儿\"、\"儿科\"、\"婴幼儿\"、\"幼儿\"、\"学龄前\"等关键词\n" +
            "- 包含儿童年龄限制（如\"3岁以下禁用\"、\"适用于2-12岁\"）\n" +
            "- 说明儿童剂量（如\"儿童用量减半\"、\"按体重计算\"）\n" +
            "- 特殊说明（如\"在医生指导下使用\"、\"慎用于儿童\"）\n" +
            "\n" +
            "#### ✘ 不属于儿童用药内容（不提取）：\n" +
            "- 仅提及\"成人\"或未指定人群的用药说明\n" +
            "- 通用禁忌症（如\"肝肾功能不全者慎用\"）\n" +
            "- 药理毒理研究中的动物实验数据\n" +
            "- 与儿童无关的不良反应描述\n" +
            "\n" +
            "### JSON输出规范（严格遵循）\n" +
            "{\n" +
            "  \"hasChildrenInfo\": \"boolean值，当childrenContent非空时为true，否则false\",\n" +
            "  \"childrenContent\": \"string值，提取的原文内容（保留标点），无则空字符串\",\n" +
            "  \"ageIndication\": \"string值，适用年龄范围描述，无则空字符串\",\n" +
            "  \"dosageInfo\": \"string值，儿童剂量信息，无则空字符串\"\n" +
            "}\n" +
            "\n" +
            "### 提取规则\n" +
            "1. **childrenContent**：\n" +
            "   - 必须是**连续的原文片段**（不做任何修改，但是不要显示重复内容）\n" +
            "   - 严格去重规则：\n" +
            "     * 完全重复表述：仅保留首次出现内容\n" +
            "       - 例：\"3岁以下禁用；3岁以下禁用\" → \"3岁以下禁用\"\n" +
            "     * 语义重复表述：保留信息最完整的一条\n" +
            "       - 例：\"儿童禁用\"和\"小儿禁用\" → 保留\"儿童禁用\"（更规范表述）\n" +
            "       - 例：\"2-5岁每次2.5ml\"和\"2至5岁患者剂量2.5ml\" → 保留\"2-5岁每次2.5ml\"（更简洁规范）\n" +
            "     * 层级包含关系：保留最全面的范围描述\n" +
            "       - 例：\"婴幼儿禁用；2岁以下禁用\" → 保留\"2岁以下禁用\"（婴幼儿通常包含2岁以下）\n" +
            "     * 相同内容不同表述：统一为标准术语\n" +
            "       - 例：\"小儿\"和\"儿童\" → 统一为\"儿童\"（药监局规范术语）" +
            "   - 长度≤100字，截取核心部分\n" +
            "   - 多处相关内容用\";\"分隔\n" +
            "   - 无相关内容时留空字符串\n" +
            "\n" +
            "2. **ageIndication**：\n" +
            "   - 仅提取明确的年龄表述\n" +
            "   - 格式示例：\"3岁以下禁用\"、\"适用于2-12岁\"\n" +
            "   - 无年龄信息时留空\n" +
            "\n" +
            "3. **dosageInfo**：\n" +
            "   - 仅提取剂量相关描述\n" +
            "   - 格式示例：\"儿童剂量为成人1/2\"、\"按体重5mg/kg\"\n" +
            "   - 无剂量信息时留空\n" +
            "\n" +
            "### 处理流程\n" +
            "1. 扫描文本寻找儿童相关关键词\n" +
            "2. 提取完整相关语句（保持原文）\n" +
            "3. 从提取内容中分离年龄和剂量信息\n" +
            "4. 按规则填充JSON字段\n" +
            "5. 根据childrenContent是否为空设置hasChildrenInfo\n" +
            "\n" +
            "### 输出示例\n" +
            "✅ 有效示例1（有儿童信息）：\n" +
            "{\n" +
            "  \"hasChildrenInfo\": true,\n" +
            "  \"childrenContent\": \"本品适用于2-12岁儿童，需在医师指导下使用；3岁以下禁用\",\n" +
            "  \"ageIndication\": \"2-12岁适用，3岁以下禁用\",\n" +
            "  \"dosageInfo\": \"\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例2（有剂量信息）：\n" +
            "{\n" +
            "  \"hasChildrenInfo\": true,\n" +
            "  \"childrenContent\": \"儿童用量：2-5岁每次2.5ml，6-12岁每次5ml\",\n" +
            "  \"ageIndication\": \"2-12岁\",\n" +
            "  \"dosageInfo\": \"2-5岁每次2.5ml，6-12岁每次5ml\"\n" +
            "}\n" +
            "\n" +
            "✅ 有效示例3（无儿童信息）：\n" +
            "{\n" +
            "  \"hasChildrenInfo\": false,\n" +
            "  \"childrenContent\": \"\",\n" +
            "  \"ageIndication\": \"\",\n" +
            "  \"dosageInfo\": \"\"\n" +
            "}\n" +
            "\n" +
            "### 绝对禁止\n" +
            "× 修改原文表述\n" +
            "× 添加解释性内容\n" +
            "× 多次输出JSON\n" +
            "× 使用非中文字符\n" +
            "× 对内容进行推断或总结\n" +
            "× 忽略去重要求保留重复内容\n" +
            "\n" +
            "请立即处理以下说明书内容：\n" +
            "\"\"\"\n" +
            "%s\n" +
            "\"\"\"\n";
    
    
    
    
    
    public static final String PRODUCTION_ENTERPRISE_STATUS_PROMPTX = "你是一名中药产业分析专家，擅长评估中药材供应链和生产企业资质。\n" +
            "\n" +
            "【任务】\n" +
            "请根据已有知识或数据，对药品 `%s` 的生产企业进行以下三项判断：\n" +
            "1. 该企业%s（或其所属集团）是否拥有独立的GAP（中药材生产质量管理规范）种植基地？\n" +
            "2. 若有，该基地种植了哪些中药材？\n" +
            "3. 这些种植的药材中，是否有至少一种属于该药品的成分（`%s`）？\n" +
            "\n" +
            "【评分规则】（满足全部条件才得分）\n" +
            "1分：该企业拥有GAP种植基地，且基地种植的药材中包含该药品的任一成分。\n" +
            "0分：该企业无GAP种植基地，或虽有但所种药材均不属于该药品成分。\n" +
            "\n" +
            "【关键说明】\n" +
            "- ‘拥有’包括企业自建、控股子公司或集团直属基地。\n" +
            "- 成分匹配需为药材名称完全一致或标准别名（如‘丹参’与‘赤芍’不互通，按规范判断）。\n" +
            "- 若信息不足或无法确认GAP基地存在，默认视为无。\n" +
            "\n" +
            "\n" +
            "【输出格式要求】\n" +
            " 输出必须严格遵循JSON格式：\n %s \n"+
            "\n" +
            "现在开始，请严格按照以上要求执行。";

    
