    public static final String PAPER_RATING_PROMPT =
            "你是一名专业的中药物经济学专家，擅长基于文献证据评估药品的经济性。\n" +
            "请根据我提供的关于 %s 的经济学相关文献（包括题目与摘要），判断该药品与其他治疗药物相比是否具有经济学优势。\n" +
            "\n" +
            "【评分标准】\n" +
            "2分：存在文献证据表明 %s 在成本-效果、成本-效用或成本-效益方面优于或不劣于对比药物（如ICER ≤ 愿付阈值、Dominated等），即具有经济学优势。\n" +
            "0分：未提供文献，或提供的文献中无直接比较，或结果显示不具经济优势（如成本更高且效果更差，或增量成本效果比超出可接受阈值）。\n" +
            "\n" +
            "【输出要求】\n" +
            "- 只返回一个阿拉伯数字：2 或 0\n" +
            "- 不要添加任何解释、标点、空格、换行或额外文本\n" +
            "- 若无法确定，默认返回 0\n" +
            "\n" +
            "【示例输出】\n" +
            "2\n" +
            "0\n" +
            "【文献内容】\n %s";

    //  String prompt = "你作为一名中药物经济学专家，请根据我提供的经济学相关文献的题目+摘要信息，判断一下" + drugInfoNew.getDrugName() + "与其他药物相比，" + drugInfoNew.getDrugName() +
    //                        "是否具有经济学优势（若未提供文献，则代表无经济学优势）：\n" +
