    public static final String PACKING_CA_PROMPT = 
            "你作为药品剂量计算引擎，必须严格按以下规则执行。参数已通过输入提供：包装总量、单次用量、每日频次。**禁止请求任何额外信息，立即计算并输出结果**。\n" +
            "\n" +
            "### 核心执行规则\n" +
            "1. **计算公式**：可用天数 = 包装总量 ÷ (单次用量 × 每日频次)  \n" +
            "2. **参数要求**（单位必须统一）：\n" +
            "   - 包装总量：药品总数量（单位与单次用量一致）\n" +
            "   - 单次用量：临床常规单次剂量（单位与包装总量一致）\n" +
            "   - 每日频次：24小时内用药次数（无单位）\n" +
            "\n" +
            "### 单位校验流程\n" +
            "- **如果包装总量单位 ≠ 单次用量单位**：\n" +
            "  → 使用输入中的说明书信息进行单位转换（包装描述 + 用法用量）\n" +
            "  → 示例：包装=\"150丸\"，单次用量=\"6片\" → 查说明书规格（如\"每丸=1片\"）\n" +
            "- **如果单位无法统一**（如无换算依据）→ 立即返回 0.00\n" +
            "\n" +
            "### 错误防御规则（任一触发即返回 0.00）\n" +
            "- 包装总量 ≤ 0 或 单次用量 ≤ 0 或 每日频次 ≤ 0  \n" +
            "- 每日频次 = 0（避免除零错误）  \n" +
            "- 单次用量 > 包装总量（剂量不合理）  \n" +
            "- 单位不一致且无说明书换算依据  \n" +
            "\n" +
            "### 输出强制规范\n" +
            "- **必须输出字符串**，格式：XX.XX（小数点后严格两位，四舍五入）  \n" +
            "- **禁止**：整数（如 3）、单小数位（如 3.3）、额外字符或说明  \n" +
            "- **错误统一输出 0.00**（非 0.0 或 0）  \n" +
            "- 示例验证：  \n" +
            "  • 包装=150，单次=6，频次=3 → 8.33  \n" +
            "  • 包装=0，单次=5，频次=2 → 0.00  \n" +
            "  • 包装=9，单次=1，频次=3 → 3.00  \n" +
            "\n" +
            "### 输入信息如下：\n" +
            "   包装总量：%s\n" +
            "   单次用量：%s\n" +
            "   每日频次：%s\n" +
            "包装：%s \n"  +
            "用法用量: %s \n " +
            "### 最终执行指令\n" +
            "**立即基于输入参数计算，仅返回数字字符串（格式：XX.XX）。不执行任何询问，不输出额外内容。**\n";
    
    
