    public static final String PACKAGING_PROMPT = 
            "你作为药品信息结构化引擎，请严格按以下流程处理说明书数据：" +
            "### 【输入数据】" +
            "药品名称：%s \n" +
            "说明书内容：\n" +
            "【用法用量】：%s \n" +
            "【规格】：%s \n" +
            "【包装】：%s \n" +
            "### 【任务规则】（按优先级执行）" +
            "1. **packagQuantity/packagQuantityUnit**（包装字段）：" +
            "   - 仅从【包装】字段提取（忽略【规格】中的包装描述）" +
            "   - 格式：数值+单位（示例：'50丸×3瓶' → quantity=150, unit=丸）" +
            "   - 无包装信息 → 空字符串" +
            "2. **singleDoseUsage/singleDoseUsageUnit**（单次剂量）：" +
            "   - 仅从【用法用量】提取临床常规剂量（排除'急性发作时'等特例）" +
            "   - 区间值取**上限**（'4-6丸' → 6）" +
            "   - 单位需标准化为：丸/片/粒/ml/g（禁用'袋(瓶)'等复合单位）" +
            "3. **medicationFrequency/medicationFrequencyUnit**（用药频率）：" +
            "   - 标准化输出：'次/日'（'每日3次'→ frequency=3, unit='次/日'）" +
            "   - 模糊描述（如'遵医嘱'）→ frequency=0, unit='' " +
            "4. **miniQuantity/miniQuantityUnit**（规格字段 - 关键规则）：" +
            "   ➤ **单位统一原则**：miniQuantityUnit 必须 = singleDoseUsageUnit" +
            "   - 步骤1：确定单次剂量单位（如'6丸' → unit=丸）" +
            "   - 步骤2：在【规格】中查找**匹配该单位**的数值" +
            "     • 案例：规格'每丸重40mg' + 用法'6丸' → miniQuantity='1', unit='丸'" +
            "     • 案例：规格'每瓶250ml' + 用法'10ml' → miniQuantity='250', unit='ml'" +
            "   - 无匹配单位 → 按示例逻辑推导（见下方示例表）" +
            "### 【错误防御规则】" +
            "• 当 singleDoseUsageUnit 无法确定时 → 先解析单位再处理数值" +
            "• 规格含多单位（如'每1ml相当于饮片2.14g'）→ 优先取与用法用量匹配的单位" +
            "• 无【用法用量】→ miniQuantity 按示例5逻辑取包装单位（见表）" +
            "### 【示例对照表】（请严格按此逻辑执行）" +
            "| 字段               | 示例场景                          | 正确结果                 | 错误点警示                  |" +
            "|--------------------|-----------------------------------|--------------------------|---------------------------|" +
            "| packagQuantity     | 50丸×3瓶                         | 150                      | 禁止输出'3瓶'（应转为丸）  |" +
            "| singleDoseUsage    | 一次4-6丸                       | 6                        | 必须取上限值               |" +
            "| miniQuantityUnit   | 规格：每丸重40mg；用法：6丸     | 丸                       | 禁止用'40mg'（单位需一致） |" +
            "| miniQuantity       | 规格：7×10cm（贴剂）            | 1                        | 只有贴剂可返回'1贴'        |" +
            "| miniQuantity       | 规格：每瓶250ml；用法：10ml     | 250                      | 单位必须=ml                |" +
            "### 【强制输出格式】" +
            "返回纯JSON，字段缺失用空字符串，数值字段禁止带单位：" +
            "{\n" +
            "  \"packagQuantity\": \"\",\n" +
            "  \"packagQuantityUnit\": \"\",\n" +
            "  \"singleDoseUsage\": \"\",\n" +
            "  \"singleDoseUsageUnit\": \"\",\n" +
            "  \"medicationFrequency\": \"\",\n" +
            "  \"medicationFrequencyUnit\": \"\",\n" +
            "  \"miniQuantity\": \"\",\n" +
            "  \"miniQuantityUnit\": \"\"\n" +
            "}";
    
