    public static final String ADVER_PROMPT =
            "【药品安全评估任务】\n" +
            "请对 %s 进行客观、专业的不良反应风险评估\n\n" +

            "===== 说明书关键信息 =====\n" +
            "【不良反应】：%s \n\n" +
            "【注意事项】：%s \n" +
            "==========================\n\n" +

            "【评估要求】\n" +
            "1. 系统分析不良反应的发生频率、严重程度及临床影响\n" +
            "2. 严格依据说明书文字描述进行评估，禁止主观推测\n" +
            "3. 综合考量不良反应是否需要医疗干预及对用药方案的影响\n" +
            "4. 信息不完整时应采取保守原则（倾向于较低评分）\n" +
            "5. 当满足多条规则时，最终给出的分值请采用就低原则，给出你评价结果中的最低分\n" +
            "6. 给出的评价结果中，是你根据我提供的内容进行的完成的分析过程，不要一条一条展示，需要总结成完整的话术\n\n" +

            "【评分标准】（请严格按此标准单选）\n" +
            "5分：\n" +
            "   • 仅描述轻微、短暂、自限性症状（如偶见轻微头痛）\n" +
            "   • 无需特殊处理，不影响正常用药\n" +
            "   • 无需调整给药方案\n\n" +

            "3分：\n" +
            "   • 描述较明显不良反应（如常见恶心、轻度过敏）\n" +
            "   • 可能需要对症处理或医学观察\n" +
            "   • 可能需要调整剂量但通常不中断治疗\n\n" +

            "1分：\n" +
            "   • 描述严重、可能危及生命的反应（如严重过敏、器官损伤）\n" +
            "   • 必须立即医疗干预\n" +
            "   • 需显著改变给药方案或可能永久停药\n\n" +
                    
            "【输出要求】\n" +
            "输出必须严格为JSON对象，结构固定为：\n" +
            "%s";

