            "   • 由国家卫健委/国家中医药管理局发布\n" +
            "   • ⚠️ 省级以下机构发布的不视为诊疗规范\n\n" +

            "✅ **专家共识**:\n" +
            "   • 标题中明确包含'共识'二字\n" +
            "   • 或内容标注'专家共识'\n" +
            "   • ⚠️ 仅'建议'、'意见'不视为共识\n\n" +

            "【权威机构定义】\n" +
            " **国家级学会 (A类)**:\n" +
            "   • 中华医学会及其下属分学会、中国医师协会\n" +
            "   • 中国药学会及其下属分学会、中华中医药学会\n" +
            "   • 国家一级学会(参见《国家一级学会名录》)\n" +

            " **非国家级机构 (B类)**:\n" +
            "   • 省/市/区县级学会\n" +
            "   • 高校/医院内部学术组织\n" +
            "   • 行业/跨区域联合团体\n" +
            "   • 国际学会中国分支机构\n\n" +

            "【评分决策树】(必须严格按序执行)\n" +
            "1 **第一层: 识别文献类型**\n" +
            "   a) 检查标题 → 是否包含'诊疗规范'或'指导原则'\n" +
            "      • 是 → 评分=10 (无需检查发布机构)\n" +
            "      • 否 → 进入1b\n" +
            "   b) 检查标题 → 是否包含'指南'二字且不含'共识'\n" +
            "      • 是 → 进入2\n" +
            "      • 否 → 进入1c\n" +
            "   c) 检查标题 → 是否包含'共识'二字\n" +
            "      • 是 → 进入3\n" +
            "      • 否 → 进入4\n\n" +

            "2 **第二层: 指南详细评分**\n" +
            "   a) 检查是否为'中成药治疗[病种]临床应用指南'\n" +
            "      • 是 → 评分=10\n" +
            "      • 否 → 进入2b\n" +
            "   b) 检查发布机构 → 是否为国家级学会或者其下属分学会(A类)\n" +
            "      • 是 → 评分=9\n" +
            "      • 否 → 评分=8\n\n" +

            "3 **第三层: 共识详细评分**\n" +
            "   a) 检查发布机构 → 是否为国家级学会或者其下属分学会(A类)\n" +
            "      • 是 → 评分=7\n" +
            "      • 否 → 评分=6\n\n" +

            "4 **第四层: 其他类型评分**\n" +
            "   a) 评分=0\n" +

            "【中医药特殊规则】\n" +
            "  中医药领域重点检查:\n" +
            "   • '中成药治疗[病种]临床应用指南' → 10分\n" +
            "   • '中医药防治[疾病]指南' → 9分(若国家级学会发布)\n" +
            "   • '中医[病种]诊疗指南' → 9分(若国家级学会发布)\n" +
            "   •   '中西医结合'相关指南按西医标准处理\n\n" +

            "【典型示例】\n" +
            "✅ 示例1: 《中成药治疗痛经临床应用指南(2021年)》\n" +
            "   • 标题含'中成药治疗...临床应用指南' → 10分\n\n" +

            "✅ 示例2: 《原发性痛经中西医结合诊疗指南》\n" +
            "   • 标题含'指南'但非'中成药治疗'类型 → 检查发布机构\n" +
            "   • 若中华中医药学会发布 → 9分\n" +
            "   • 若除国家级学会外的其他学会发布 → 8分\n\n" +

            "✅ 示例3: 《新冠肺炎中医药防治专家共识》\n" +
            "   • 标题含'共识' → 共识类\n" +
            "   • 若国家级学会发布 → 7分\n" +
            "   • 若除国家级学会外的其他学会发布 → 6分\n\n" +

            "✅ 示例4: 《骨关节炎中西医结合诊疗指南》\n" +
            "   • 标题含'指南' → 检查发布机构\n" +
            "   • 中国中西医结合学会风湿病专业委员会国家级学会发布 → 9分\n" +

            "【输出格式要求】\n" +
            "1 输出必须严格遵循JSON格式：\n %s \n"+
            "2 验证规则:\n" +
            "   • 分数范围: 0、6、7、8、9、10\n" +
            "   • 必须包含所有提供的指南ID\n" +
            "   • 不得添加未提供的ID\n" +
            "   • explanation字段需说明:\n" +
            "      - 文献类型判定\n" +
            "      - 关键评分依据\n" +
            "      - 有争议时的裁决理由\n\n" +

            "【当前任务】\n" +
            "请对以下指南进行评分，药品名称: %s" +
            "指南信息: %s";


